Task: Put the red cube into the red tray and the blue cube into the blue tray.

Skill code (numbered):
  1| import math
  2| 
  3| def run(robot):
  4|     """Sort cubes by colour into matching trays."""
  5|     robot.home()
  6| 
  7|     # Get current scene description
  8|     obs = robot.observe()
  9| 
 10|     # Separate cubes and trays
 11|     cubes = {name: obj for name, obj in obs['objects'].items() if obj['shape'] == 'cube'}
 12|     trays = {name: fix for name, fix in obs['fixtures'].items() if fix['kind'] == 'tray'}
 13| 
 14|     # Map colour -> tray name (e.g., 'red' -> 'red_tray')
 15|     colour_to_tray = {}
 16|     for name, fix in trays.items():
 17|         colour_to_tray[fix['color']] = name
 18| 
 19|     overall_success = True
 20| 
 21|     for cube_name, cube in cubes.items():
 22|         colour = cube['color']
 23|         tray_name = colour_to_tray.get(colour)
 24|         if tray_name is None:
 25|             robot.log(f"No tray found for colour '{colour}'")
 26|             overall_success = False
 27|             continue
 28| 
 29|         # Get up-to-date poses (perception is noisy)
 30|         cube_pose = robot.get_pose(cube_name)
 31|         tray_pose = robot.get_pose(tray_name)
 32| 
 33|         if not _pick_and_place(robot, cube_pose, tray_pose):
 34|             robot.log(f"Failed to place {cube_name} into {tray_name}")
 35|             overall_success = False
 36| 
 37|     return overall_success
 38| 
 39| 
 40| def _pick_and_place(robot, cube_pose, tray_pose):
 41|     """Attempt one pick‑and‑place cycle. Returns True on success."""
 42|     max_attempts = 2
 43|     lift_height = 0.10          # safe travel height above the table
 44|     grasp_offset = 0.08         # how far above the cube centre we initially approach
 45|     probe_down = 0.02           # additional downward move before closing fingers
 46|     place_offset = 0.02         # how far above the tray bottom we release
 47| 
 48|     for attempt in range(max_attempts):
 49|         try:
 50|             # 1. Move above the cube
 51|             above_cube = [cube_pose['pos'][0], cube_pose['pos'][1], lift_height]
 52|             robot.move_to(*above_cube, speed=0.2)
 53| 
 54|             # 2. Descend to a grasp approach height (just above the cube centre)
 55|             approach_z = cube_pose['pos'][2] + grasp_offset
 56|             robot.move_to(cube_pose['pos'][0], cube_pose['pos'][1], approach_z,
 57|                           speed=0.05, yaw=cube_pose['yaw'])
 58| 
 59|             # 3. Probe a little closer to the cube
 60|             grasp_z = cube_pose['pos'][2] + grasp_offset - probe_down
 61|             robot.move_to(cube_pose['pos'][0], cube_pose['pos'][1], grasp_z,
 62|                           speed=0.05, yaw=cube_pose['yaw'])
 63| 
 64|             # 4. Close fingers
 65|             if not robot.grasp():
 66|                 robot.release()  # ensure hand is open before retrying
 67|                 continue
 68| 
 69|             # 5. Verify we actually hold something
 70|             if robot.holding() is None:
 71|                 robot.release()
 72|                 continue
 73| 
 74|             # 6. Lift the cube to safe height
 75|             robot.move_to(cube_pose['pos'][0], cube_pose['pos'][1], lift_height,
 76|                           speed=0.05)
 77| 
 78|             # 7. Refresh tray pose and move above the target tray
 79|             tray_pose = robot.get_pose(tray_name)  # latest perception
 80|             above_tray = [tray_pose['pos'][0], tray_pose['pos'][1], lift_height]
 81|             robot.move_to(*above_tray, speed=0.2)
 82| 
 83|             # 8. Lower to just above the tray bottom
 84|             place_z = tray_pose['pos'][2] + place_offset
 85|             robot.move_to(tray_pose['pos'][0], tray_pose['pos'][1], place_z,
 86|                           speed=0.05, yaw=tray_pose['yaw'])
 87| 
 88|             # 9. Release the cube
 89|             robot.release()
 90|             robot.wait(0.05)  # brief pause to let the object settle
 91| 
 92|             # 10. Retract to safe height
 93|             robot.move_to(tray_pose['pos'][0], tray_pose['pos'][1], lift_height,
 94|                           speed=0.05)
 95| 
 96|             # 11. Simple verification: cube should be released and near tray centre
 97|             obs_after = robot.observe()
 98|             held = robot.holding()
 99|             if held is not None:
100|                 robot.log("Verification failed: still holding after release")
101|                 return False
102|             cube_after = obs_after['objects'].get(cube_name)
103|             if cube_after is None:
104|                 robot.log("Verification failed: cube disappeared from observation")
105|                 return False
106|             dx = cube_after['pos'][0] - tray_pose['pos'][0]
107|             dy = cube_after['pos'][1] - tray_pose['pos'][1]
108|             if math.hypot(dx, dy) > 0.04:  # 4 cm tolerance
109|                 robot.log(f"Verification failed: cube offset ({dx:.3f},{dy:.3f}) too large")
110|                 return False
111| 
112|             return True  # success for this cube
113| 
114|         except Exception as e:  # catches MotionError and other unexpected issues
115|             robot.log(f"Attempt {attempt+1} failed: {e}")
116|             robot.release()  # try to leave the hand open
117|             continue
118| 
119|     # If we exit the loop, all attempts failed
120|     return False

